?><div class="app-layout"><?php require_once __DIR__.'/../includes/sidebar.php';?><main class="app-main"><header class="topbar"><button class="menu-toggle"><i class="fa-solid fa-bars"></i></button><div class="topbar-user"><b><?=e($user['name'])?></b><span>Student</span></div><div class="avatar"><?=e(strtoupper(substr($user['name'],0,2)))?></div></header><div class="content"><div class="page-header"><div><p>UPDATES</p><h1>Notifications</h1></div></div><section class="panel"><?php foreach($notifications as $n):?><article class="notification"><i class="fa-solid fa-bell"></i><div><?php if($n['link']):?><a href="<?=e($n['link'])?>"><b><?=e($n['title'])?></b></a><?php else: ?><b><?=e($n['title'])?></b><?php endif; ?><p><?=e($n['message'])?></p><small><?=date('d M Y, h:i A',strtotime($n['created_at']))?></small></div></article><?php endforeach;if(!$notifications):?><p>No notifications yet.</p><?php endif;?></section></div><?php require_once __DIR__.'/../includes/footer.php';?></main></div>
